<?php
declare(strict_types=1); namespace McpEmail\Tools;
use McpEmail\Config; use McpEmail\Mail\ImapClient; use Throwable;
final class ListFoldersTool implements ToolInterface {public function name():string{return 'list_folders';}public function definition():array{return ['title'=>'Mailboxfolders','description'=>'Geeft beschikbare IMAP-folders en een speciale classificatie. Aantallen kunnen null zijn wanneer de server geen status aanbiedt.','inputSchema'=>['type'=>'object','properties'=>['account'=>['type'=>'string']],'additionalProperties'=>false]];}public function call(array $a):array{$c=null;try{$c=ImapClient::connect(Config::getAccount(isset($a['account'])?(string)$a['account']:null),'INBOX');$out=[];foreach($c->folders() as $f)$out[]=['name'=>$f,'messages'=>strcasecmp($f,'INBOX')===0?$c->messageCount():null,'unread'=>strcasecmp($f,'INBOX')===0?count($c->searchUids('UNSEEN')):null,'classification'=>$this->type($f)];return Support::apiSuccess(['folders'=>$out]);}catch(Throwable){return Support::apiError('IMAP_CONNECTION_FAILED','Mailboxfolders konden niet worden opgehaald.');}finally{$c?->close();}}private function type(string $f):string{$v=strtolower($f);return match(true){$v==='inbox'=>'inbox',str_contains($v,'spam')||str_contains($v,'junk')=>'spam',str_contains($v,'sent')||str_contains($v,'verzonden')=>'sent',str_contains($v,'trash')||str_contains($v,'prullen')=>'trash',str_contains($v,'archive')||str_contains($v,'archief')=>'archive',default=>'other'};}}
